        content: "피나스테아정은 피나스테리드 5mg을 1일 1회 식사와 관계없이 경구투여해요. 아침이든 저녁이든 매일 같은 시간에 복용하면 혈중 농도를 일정하게 유지할 수 있어요.\n\n증상이 개선되더라도 최소 6개월간 치료를 지속해야 해요. 의사의 지시 없이 임의로 중단하면 전립샘이 다시 비대해질 수 있어요. 신부전 환자(크레아티닌청소율 9.0 mL/min)도 용량 조절 없이 동일하게 복용해요.\n\n정제를 부수거나 분쇄하지 않고 통째로 삼켜요. 피나스테리드 가루가 임산부 피부에 흡수되면 남성 태아에 위험할 수 있어요. 피나스테아정 복용 중 복용을 잊었다면 생각난 즉시 복용하고, 다음 시간이 가까우면 건너뛰세요.",
