        "content": "기본 복용법부터 지키는 게 출발이에요. 식약처 허가사항은 일반적으로 1일 1회 1정(1mg)을 식사와 관계없이 투여한다고 안내해요. 용량을 늘려도 유효성이 증대된다는 근거가 없으니, 효과를 빨리 보려고 임의로 증량하면 안 돼요. 증량은 부작용 위험만 키우죠.\n\n지병이 있다면 모니터링이 핵심이에요. 허가사항은 지방과부하로 특별한 위험이 예상되는 환자에게 투여할 때 혈장지질치를 점검할 것을 권장해요. 점검 결과 지방의 체외배설이 불충분하면 투여를 적절히 조절하고, 다른 정주용 지질제를 함께 쓴다면 부형제로 섞인 지질량을 고려해 그 지질제 양을 줄여야 하죠. 간 질환이 있는 분은 복용 전 그 사실을 의사에게 알려 신중 투여 여부를 정하세요.\n\n검사 전 알릴 점도 있어요. 허가사항에 따르면 18~41세 환자에서 PSA 평균값이 12개월째 감소했어요. 그래서 전립선 검사를 받을 땐 피나테크정 복용 중임을 의사에게 알려 결과를 적절히 해석하도록 해야 해요. 약 선택이나 중단은 반드시 의사와 상의하세요."
