        content: "피나드정의 주성분은 피나스테리드(Finasteride) 5mg이에요. 피나스테리드는 5알파환원효소 2형을 억제해서 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막아요. 전립샘(전립선) 내 DHT 농도를 줄여 비대해진 전립샘의 크기를 줄여주는 원리예요.\n\n(주)이든파마에서 제조한 피나드정은 프로스카(Proscar)의 제네릭 의약품이에요. 피나스테리드 5mg은 전립샘비대증 치료 용량으로, 탈모 치료 용량(1mg)과는 다른 적응증이에요. 정제 형태이며 필름코팅이 돼 있어요.\n\n전립샘비대증에서 DHT는 전립샘 세포 증식을 촉진하는 핵심 호르몬이에요. 피나드정 복용 시 전립샘 크기가 퇴행(축소)하면서 요도 압박이 줄어들어 배뇨 증상이 개선돼요. 장기 복용 시 수술 필요성도 감소해요.",
