        content: "JW피나스테리드정의 주성분은 피나스테리드(Finasteride) 1mg이에요. 피나스테리드는 5알파환원효소 2형(5-alpha reductase type 2)을 선택적으로 억제하는 성분이에요. 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막아서 두피 모낭 위축을 방지해요.\n\nJW피나스테리드정은 프로페시아의 제네릭 의약품이에요. 정제 형태의 필름코팅정으로, 코팅이 주성분과의 접촉을 방지해 임산부가 정상적으로 취급할 때 안전해요. 식약처 생동성 시험을 통과해 오리지널과 동등한 효능이 확인됐어요.\n\nDHT는 유전적으로 민감한 모낭을 축소시키는 주범이에요. JW피나스테리드정 복용 시 혈중 DHT 농도를 약 65~70% 줄여서 위축된 모낭이 다시 굵은 모발을 만들기 시작해요. 정제를 부수거나 분쇄하면 안 돼요.",
