        "content": "식약처 허가사항이 가장 강하게 막는 대상은 여성과 18세 미만 소아예요. 이 약은 피부를 통해 흡수돼요. 그래서 임신했거나 임신 가능성이 있는 여성은 누출된 캡슐에 닿기만 해도 남자 태아 외부 생식기 발달에 위험을 줄 수 있어 취급 자체가 금지돼요. 캡슐이 새어 약과 닿았다면 그 부위를 즉시 물과 비누로 씻어야 하죠.\n\n동반질환·병용 관점의 금기와 주의는 이래요. 다른 5α-환원효소 억제제를 복용 중이거나, 강력한 CYP3A4 억제제(예: 리토나비르)를 만성 복용 중이면 처방 전에 반드시 알려야 해요. 주의 투여 대상은 간장애 환자, 그리고 요잔뇨량이 크거나 중증 요류 감소가 있는 환자예요. 간에서 광범위하게 대사되고 반감기가 약 3~5주로 긴 약이라 간이 관건이죠. 한 가지 더, 두타온연질캡슐 복용 중에는 PSA 수치가 낮게 나올 수 있어요. 전립선 검사를 받을 일이 있으면 복용 사실을 의사에게 꼭 알리고, 마지막 복용 후 6개월이 지날 때까지 헌혈은 피하세요."
