        "content": "두타텍트연질캡슐 30캡슐의 기준가는 22000원이에요. 하루 한 캡슐을 먹으니 이 30캡슐이 딱 한 달치죠. 그래서 한 달 비용도 22000원으로 떨어져요. 매일 한 캡슐을 전제로 한 달을 셈하면 이만큼 들어요.\n\n같은 두타스테리드 0.5mg 묶음에는 45개 품목이 나와 있어요. 그 줄 안에서 두타텍트연질캡슐은 중상위 위치예요. 맨 아래쪽엔 30정 6000원, 1정에 약 200원 하는 휴메리나정, 케이두타다트정, 유힐릭스정 같은 정제들이 깔려 있죠. 동일 성분 제네릭이라 효능·효과는 식약처 허가 기준으로 한데 묶이고, 가격만 제형과 제조사, 파는 곳에 따라 벌어져요.\n\n여기 쓴 22000원은 실거래가가 아닌 기준가라는 점을 짚어 둘게요. 약국마다 실제로 파는 값은 조금씩 다를 수 있어요. 같은 성분 제품의 단가를 한 화면에서 견주려면 아래 버튼을 눌러 확인하세요."
