        "content": "부작용 관리의 첫 단추는 두 가지예요. 정해진 한 캡슐을 넘기지 않는 것, 그리고 알을 깨지 않는 것이죠. 연질 형태를 깨물면 안쪽 액이 점막에 닿아 자극이 올 수 있으니, 그대로 삼키는 습관만으로도 군더더기 자극을 덜어내요. 식약처 허가사항에 실린 남성형 탈모 3상 임상시험에서는 두타스테리드 0.5mg을 6개월 투여했을 때 발기기능장애가 184명 가운데 10명(5%), 성욕감소가 4명(2%)에서 나타났어요. 위약군보다 살짝 잦았던 항목들이죠.\n\n이런 성기능 쪽 반응은 대체로 가볍거나 중간 정도였고, 투여를 이어가는 사이 가라앉은 사례가 많았어요. 그래도 허가사항은 약을 끊은 뒤에도 얼마간 남을 수 있다고 덧붙여요. 국내 시판 후 조사에서도 남성형 탈모로 이 약을 받은 성인 남성 712명 중 약과의 연관을 부인하기 어려운 이상반응 발현율이 9.3%로 집계됐고, 성욕감소와 발기부전이 주로 올라왔죠.\n\n요약하면 양을 부풀려 노출을 키우거나 캡슐을 깨 흡수를 들쑥날쑥하게 만드는 일만 안 하면 돼요. 매일 한 캡슐을 통째로 넘기는 단순한 루틴이 위험을 절반은 덜어줘요. 몸에 낯선 신호가 보이면 혼자 버티지 말고 의사를 찾으세요."
