        "title": "두타케어정 흔한 부작용과 드문 부작용은 어떻게 나뉘나요?",
        "sectionType": "comparison",
        "content": "식약처 허가사항으로 보면 부작용은 대부분 경증이거나 중등증이에요. 손이 가장 많이 닿는 곳은 생식기계예요. 남성형 탈모 위약대조 3상(투여군 n=184)에서 6개월간 발기기능장애가 5%, 성욕감소가 2% 나왔어요. 위약군은 각각 3%와 1%에 그쳤네요. 탈모 목적으로 먹는 젊은 층이 자주 마주치는 칸이고요.\n\n전립선 비대증 임상은 다른 숫자를 보여 줘요. 연령 47~94세 남성을 둔 3상에서 두타스테리드 투여군은 1년차 발기부전 6%(위약 3%), 성욕 감소 4%(위약 2%)로 탈모 임상보다 높았어요. 고령에서 먹는다면 이 줄을 먼저 봐요.\n\n빈도가 낮은 칸도 결코 가볍지 않아요. 고환통이나 고환 부기, 남성 유방암은 시판 후 매우 드물게 올라온 항목이고요. 젊은 층은 또 달라요. 국내 탈모 조사(18~41세 712명) 약물유해반응 9.3% 안에 SGPT·SGOT 증가, 지방간 같은 간 신호가 섞여 있었어요. 자주 보이는 건 성기능, 드문 건 생식계·간 쪽으로 갈려요.",
        "data": "[{\"label\":\"발기기능장애\",\"freq\":\"탈모 6개월 5% / 전립선 1년 6%\",\"note\":\"위약 각각 3%. 중단 후 지속 가능\",\"color\":\"orange\"},{\"label\":\"성욕감소\",\"freq\":\"탈모 6개월 2% / 전립선 1년 4%\",\"note\":\"위약 1%·2%\",\"color\":\"yellow\"},{\"label\":\"간 관련 신호\",\"freq\":\"국내 탈모조사 9.3% 내 보고\",\"note\":\"SGPT·SGOT 증가·지방간(18~41세)\",\"color\":\"orange\"},{\"label\":\"고환통·남성 유방암\",\"freq\":\"매우 드물게 (시판 후)\",\"note\":\"연령 무관 보고\",\"color\":\"gray\"}]"
