        "content": "두타케어정 0.5mg 30정 기준가는 22,000원이에요. 1정당 약 733원꼴이죠. 하루 한 알씩이라 30정이 딱 한 달 분량이고요. 식약처에 올라온 두타스테리드 0.5mg 동일성분 45종 가운데, 1정 단가로는 중상위인 30위쯤에 놓여요.\n\n동일성분 45종의 1정 단가는 200원부터 1,267원까지 넓게 흩어져 있어요. 휴메리나정, 케이두타다트정, 유힐릭스정은 30정 6,000원, 1정 200원짜리 최저가 그룹이라 두타케어정과 격차가 꽤 나고요. 전문의약품이라 같은 성분 안에서 처방으로 갈아탈 여지가 있어요. 나이나 동반 질환이 있다면 진료 때 약값까지 함께 상의하면 좋네요. 여기 적은 숫자는 기준가예요. 지금 약국 최저가는 아래 버튼을 눌러 확인하세요."
