    "metaDescription": "두타프렌정0.5밀리그램(두타스테리드)은 다산제약 전문의약품으로 식약처 품목번호 202002131로 허가되었다. 30정 기준가 22,000원, 1정당 733원이며 두타스테리드 0.5mg 45개 제품 단가 분포(200~1,267원)의 가운데에 놓인다. 진료·처방으로 약국에서 살 때 드는 실제 비용과 같은 성분 저가 정제까지 허가사항으로 정리했습니다.",
