        "content": "곧장 약을 멈춰야 하는 첫 단서는 알레르기 신호예요. 대웅바이오 품목번호 201908540 식약처 허가사항에는 시판 후 매우 드물게 발진, 가려움증, 두드러기, 국소 부종, 심각한 피부반응, 혈관 부종이 접수됐다고 실려 있어요. 이 가운데 입술이나 얼굴이 붓는 혈관 부종은 응급에 가까워서, 보이는 순간 복용을 멈추고 진료를 받아야 해요.\n\n가슴 쪽 변화도 가볍게 넘기면 곤란해요. 멍울이 만져지거나 유두에서 분비물이 나오면 바로 의사에게 알리라는 게 허가사항 권고인데, 임상과 시판 후 보고에 남성 유방암 사례가 있었던 까닭이죠. 이유 없이 마음이 처지는 우울 증상도 드물게 보고된 항목이라, 평소와 다른 무기력이 길게 가면 그냥 지나치지 마세요.\n\n반면 굳이 끊지 않고 지켜봐도 되는 변화로 사정량이 조금 주는 일이 있어요. 허가사항은 이 정도는 정상 성기능을 막지 않는 것으로 봐요.",
