        "content": "이 약을 다룰 때 가장 신경 쓰이는 부분이 여성 접촉이에요. 허가사항은 약이 피부로 침투한다는 점을 들어, 임신했거나 임신 가능성이 있는 여성은 손에 드는 것조차 안 된다고 규정해요. 코팅이 온전한 알약일 땐 위험이 낮지만, 깨지거나 부서진 조각이 생기면 그 단면이 피부에 직접 닿으면서 흡수 경로가 열려요.\n\n원인을 거슬러 가면 호르몬 작용이 있어요. 피부로 들어온 두타스테리드가 남자 태아의 디하이드로테스토스테론(DHT) 농도를 낮추면, 바깥 생식기가 제대로 만들어지지 못할 수 있어요. 그래서 허가사항은 여성에게 약을 다룰 때마다 조심하고 부서진 조각엔 손대지 말라고 안내하며, 같은 맥락에서 소아의 접촉도 차단해요.\n\n해법은 단순해요. 조각이 떨어져 나오지 않게 통째로 두고, 임신부가 있는 집이라면 받은 용기 그대로 보관하면 돼요. 더해 수혈로 임신부에게 약이 닿는 길을 끊으려고, 남성은 마지막 복용일에서 6개월 전까진 헌혈을 미뤄야 한다고 허가사항에 적혀 있어요."
