        "content": "허가사항이 명확히 못 박은 절대 금기는 셋이에요. 여성은 복용도 접촉도 안 되고, 18세 미만 소아는 안전성과 유효성이 확립되지 않아 제외돼요. 두타스테리드나 같은 계열 5α-reductase 억제제에 과민증을 겪었던 사람도 빠져야 하죠.\n\n금기까지는 아니어도 신중히 투여할 대상이 있어요. 임신을 계획하는 성인 남성은 생식능이 영향받을 수 있어 의사 판단 아래 조심해서 먹고, 잔뇨량이 많거나 요류가 크게 감소한 환자, 간장애 환자도 주의해야 해요. 간장애가 있으면 반감기가 약 3~5주로 길어 한층 살펴야 하고요.\n\nREDUCE 임상에서는 위약 0.5%보다 이 약 투여군 1.0%에서 Gleason 등급 8~10 고등급 전립선암이 더 많이 나와, 전립선암을 정기적으로 점검하도록 권해요. 강력한 CYP3A4 억제제 병용이나 다른 5α-reductase 억제제 중복 복용도 삼가는 게 맞아요."
