        content: "메디녹실액의 주성분은 미녹시딜(Minoxidil) 5%예요. 미녹시딜은 두피 혈관을 확장시켜 모낭으로 가는 혈류량을 늘리고, 위축된 모낭을 다시 활성화하는 성분이에요.\n\n(주)동구바이오제약에서 제조한 메디녹실액은 액제 제형이에요. 스포이트나 스프레이를 이용해 두피에 직접 도포해요. 에탄올과 프로필렌글리콜이 용매로 들어있어요.\n\n미녹시딜은 원래 고혈압 치료제로 개발됐지만, 다모증(털 과다 성장) 부작용이 발견되면서 외용 탈모 치료제로 재개발된 성분이에요. 액제에 포함된 프로필렌글리콜이 두피 자극의 주요 원인이에요.",
