        "content": "식약처 허가사항이 정한 효과 평가 시점은 3개월이에요. 일반적으로 3개월 이상 복용해야 치료효과를 볼 수 있고, 효과를 유지하려면 지속적으로 복용하라고 안내하죠. 반대로 복용을 중단하면 12개월 내에 치료효과는 사라져요. 끊으면 원위치예요.\n\n여기서 동반질환 관점이 끼어들어요. 간기능에 이상이 있어 신중 투여로 시작한 경우, 3개월이라는 평가선은 그대로지만 그 기간 동안 간 상태를 같이 지켜봐야 하죠. 효과가 나오는 시점을 앞당기겠다고 용량을 올리는 건 의미가 없어요. 허가사항은 용량을 증량해도 유효성이 증대된다는 근거가 없다고 분명히 적어요. 그러니 1일 1회 1정을 3개월, 그 뒤로도 꾸준히. 이 리듬을 지키면서 정기적으로 효과와 안전을 같이 평가받는 게 그로모정 효과를 제대로 보는 길이에요. 짧게 끊으면 평가 기준 자체를 못 채워요."
