        "content": "페로시아정 30정의 기준가는 15,000원이에요. 하루 한 알이니 30정이면 대략 한 달 분량이네요. 한 알로 나눠 보면 500원 남짓이에요. 다만 같은 약도 약국마다 값이 달라, 진짜 최저가는 아래 가격비교 버튼에서 확인하는 편이 정확해요.\n\n피나스테리드 1mg 정제는 통에 담긴 알 수가 가지각색이라, 비교는 결국 1알 단가로 모여요. 같은 성분 알약 가운데는 1정 300원대로 시작하는 소포장도, 알을 잔뜩 담아 단가를 낮춘 큰 통도 섞여 있죠. 효능 기준선이 같은 1mg 정제면 동등하니, 남는 변수는 알당 얼마인지와 포장이 내 복용 주기에 맞는지뿐이에요. 처방을 받은 뒤 단가가 낮은 쪽으로 고르면 길게 먹을 때 드는 비용을 아낄 수 있어요."
