        "content": "식약처 허가사항(품목번호 200704541)이 가장 강조하는 즉시 중단 신호는 정신과적 증상이에요. 피나스테리드 1mg을 투여한 환자에서 우울한 기분과 우울증이 보고됐고, 이보다 적은 건수로 자살생각을 포함한 기분변형도 보고됐죠. 허가사항은 이런 증상이 발생하면 투여를 중단하고 의료전문가에게 상담하라고 못 박았어요. 연령과 무관하게 가장 먼저 봐야 할 신호예요.\n\n유방 변화도 중단·상담 트리거예요. 멍울, 통증, 유두분비물, 유방비대, 압통, 신생물을 포함한 유방의 변화가 있으면 신속히 의사에게 보고하도록 허가사항이 안내해요. 시판 후 보고에 남성 유방암 사례가 있었기 때문이죠.\n\n응급에 가까운 건 과민반응이에요. 입술·혀·목구멍·얼굴의 종창을 포함한 혈관부종, 두드러기, 가려움 같은 반응이 나타나면 바로 멈추고 진료를 받아야 해요. 반대로 사정량이 조금 주는 정도는 정상 성기능을 방해하지 않는 비응급 변화라, 같은 부작용이라도 무게가 달라요. 헷갈리면 의사·약사에게 먼저 물어보세요.",
