        "content": "먹으면 안 되는 사람은 허가사항이 또렷하게 못 박아 뒀어요. 임부나 임신 가능성이 있는 여성이 1순위 금기인데, 남성 태아 외부생식기 비정상을 부를 수 있어서예요. 소아환자도 안전성·유효성이 확립되지 않아 제외되고요. 탈모 허가 연령을 만 18~41세로 좁힌 것과 같은 이유죠. 이 약이나 그 성분에 과민반응을 보인 적이 있다면 그 역시 금기예요.\n\n겹쳐 먹는 것도 막아요. 양성전립샘비대증 등으로 이 약 5mg이나 다른 5α-환원효소 억제제를 이미 복용 중이라면 함께 쓰면 안 돼요. 유당이 들어 있어 갈락토오스 불내성, Lapp 유당분해효소 결핍증, 포도당-갈락토오스 흡수장애 같은 유전 질환자도 투여 금기고요. 대두유·콩·땅콩 알레르기가 있다면 주의가 필요해요.\n\n반면 약물 상호작용은 부담이 덜한 편이에요. 허가사항은 임상적으로 의미 있는 상호작용이 확인된 바 없다고 적었고, 이 약은 CYP-450 효소계를 건드리지 않는다고 알려졌죠. 와르파린·디곡신 등과 본 임상에서도 문제 되는 상호작용은 없었어요. 다만 간 대사 부담이 있어 간 기능 이상이 있으면 신중 투여 대상이라, 시작 전 의사와 상의해요."
