        "content": "유로다트연질캡슐은 (주)씨티씨바이오가 내놓은 두타스테리드 0.5mg 연질캡슐이에요(식약처 품목번호 201603673). 허가받은 적응증은 두 줄기예요. 한 줄기는 성인 남성(만18~50세)의 남성형 탈모, 다른 한 줄기는 양성 전립선 비대증이에요. 한 캡슐이 두 자리를 겸하죠.\n\n이 글이 처음부터 끝까지 붙잡는 자는 먹는 사람의 몸 사정이에요. 함량이 똑같은 0.5mg이어도, 간 수치가 어느 선인지·다른 지병을 끼고 있는지에 따라 출발 문턱과 안전 여유가 달라져요. 두타스테리드는 간에서 광범위하게 대사되고 몸에서 빠지는 반감기만 약 3~5주라, 약효를 몸 상태와 떼어 말하기 어려워요. 더구나 식약처 허가사항은 여성과 18세 미만에게는 투여를 금하고, 탈모 적응증을 만18~50세 남성으로 한정해요. 내 조건이 이 안에 드는지부터 진료실에서 가려야 해요.",
