        "content": "당장 약을 멈춰야 하는 첫 번째 단서는 알레르기 쪽이에요. 광동제약 품목번호 201405883 식약처 허가사항을 보면, 발진과 가려움증, 두드러기, 부분적 부종, 중한 피부반응, 혈관 부종이 시판 후 매우 드물게 접수됐다고 나와요. 그중 입가나 얼굴이 부어오르는 혈관 부종은 응급에 가까운 신호라, 보이는 순간 복용을 끊고 병원으로 가는 게 맞아요.\n\n가슴 부위 변화 역시 그냥 두면 안 돼요. 멍울이 잡히거나 유두에서 분비물이 비치면 곧장 의사에게 전하라고 허가사항이 당부해요. 임상과 시판 후 자료에 남성 유방암 보고가 있었던 탓이죠. 기분이 까닭 없이 가라앉는 우울 증상도 매우 드물게 올라온 만큼, 평소와 다른 무기력이 길어지면 흘려보내지 마세요.\n\n반대편에 두고 볼 변화도 있어요. 사정량이 다소 줄어드는 현상인데, 허가사항은 이게 정상적인 성기능을 가로막지는 않는 것으로 본다고 적어요. 즉시 끊을 신호와 지켜볼 변화, 이 둘을 갈라 두면 판단이 쉬워져요.",
