        "answer": "둘 다 괜찮아요. 식약처 허가사항은 이 약을 식사와 관계없이 복용할 수 있다고 밝혀요. 끼니 앞뒤를 가릴 필요가 없으니 식전·식후 어느 쪽이든 본인 생활에 맞춰 한 시각을 정하면 돼요. 중요한 건 시점이 아니라 매일 빠뜨리지 않는 일관성이에요. 권장용량 자체가 1일 1회 1캡슐(0.5mg)이라 하루 한 번만 맞추면 되니까, 아침에 챙기든 잠들기 전에 챙기든 본인이 가장 잊지 않을 시각으로 묶어 두는 편이 낫죠. 다만 캡슐을 물 없이 삼키려다 목에 걸리는 경우가 있으니, 끼니와 무관하더라도 충분한 물과 함께 넘기는 습관은 지키는 게 좋아요."
