        "content": "주성분은 두타스테리드 0.5mg 한 가지예요. (주)대웅제약이 내놓은 전문의약품이고, 식약처 품목번호로는 201507299로 등록돼 있죠. 허가받은 적응증은 둘로 나뉘어요. 첫째가 양성 전립선 비대증 치료, 둘째가 만 18세부터 50세까지 성인 남성의 남성형 탈모(androgenetic alopecia)고요. 본문은 탈모로 먹는 쪽에 맞춰 갈게요. 연령 상한이 50세라 그 위 환자의 유효성 자료는 허가사항에 없고, 여성과 18세 미만 소아는 처음부터 복용 금기예요. 같은 두타스테리드 0.5mg 제품이 식약처에 45개나 등재될 만큼 흔한데, 두타겟연질캡슐을 가르는 결정적 차이가 제형이에요. 단단한 알약이 아니라 젤 껍질이 약물을 품은 연질캡슐이죠. 제형이 바뀌면 넘기는 법도 달라지니, 복용 단계부터 풀어 갈게요.",
