        "content": "먼저 복용하면 안 되는 사람을 구분해요. 허가사항은 세 부류를 금기로 못 박죠. 여성, 18세 미만 소아, 그리고 이 약이나 다른 5알파환원효소 억제제에 과민증이 있는 사람이에요. 여기에 더해 조심스레 써야 하는 경우가 따로 있어요. 임신을 준비하는 성인 남성은 생식능이 흔들릴 수 있어 의사 판단을 거쳐야 하고, 요잔류량이 많거나 중증 요류 감소가 있는 사람도 주의 대상에 들어가요. 간장애가 있다면 더 신경 써야 하죠. 이 약은 몸 안에서 폭넓게 대사되는 데다 반감기가 약 3~5주로 길어, 간 기능이 떨어진 사람에겐 신중 투여가 권고돼요. 함께 먹는 약도 점검 거리예요. 리토나비르처럼 강력한 CYP3A4 억제제를 오래 복용하는 사람은 같이 먹을 때 주의가 붙어요. 이 약 자체가 사람의 CYP3A4로 분해되는 탓이죠. 검사 한 가지도 변수예요. 투여 6개월이 지나면 총 혈청 PSA 농도가 약 50%까지 내려가서, 전립선암 검진 전에 복용 사실을 의사에게 미리 알려야 수치 해석이 어긋나지 않아요. 보관은 허가사항대로 처음 받은 용기째가 원칙이고, 다른 통에 옮기지만 않으면 돼요."
