        "content": "동아에스티(주)가 만든 두타반연질캡슐0.5밀리그램(두타스테리드)은 두타스테리드 0.5mg을 담은 전문의약품이에요. 식약처 품목번호로는 201007777이 붙어 있죠. 적응증이 둘인데, 양성 전립선 비대증과 함께 성인 남성(만 18~50세)의 남성형 탈모(androgenetic alopecia)가 허가사항에 올라 있어요.\n\n갈림길은 연질캡슐이라는 형태에 있어요. 무른 약물을 말랑한 외피가 둘러싼 구조라, 내용물이 입안에 노출되면 구강 인두점막을 자극할 수 있다고 허가사항이 짚어요. 그러니 깨물거나 가르지 말고 그대로 삼키라는 지침이 붙죠. 식사 여부와 무관하게 먹어도 된다는 안내도 같이 있어요.\n\n새겨 둘 대목이 연질캡슐과 또 얽혀요. 두타스테리드는 피부로 스며드는 성분이라, 캡슐이 새어 약이 묻으면 임신 가능성이 있는 여성은 곧장 물과 비누로 닦아내야 한다고 적혀 있죠. 누출에 정제보다 민감한 만큼, 이 글은 효능을 짧게 두고 상태별 부작용 해석에 무게를 실을게요."
