        "content": "먼저 먹으면 안 되는 사람부터 짚을게요. 케라티딘캡슐에 과민증이 있는 사람과 12세 미만 소아는 복용하지 마세요. 임부 또는 임신 가능성이 있는 여성과 수유부, 황색5호에 과민증이 있거나 경험한 적이 있는 사람은 복용 전에 의사 또는 약사와 상의해야 해요. 식약처 허가사항에 명시된 내용이에요.\n\n탈모 종류에 따라서도 가려야 해요. 흉터로 인한 탈모, 안드로겐 유전성 탈모증, 남성형 대머리에는 복용하지 마세요. 이 약은 손상 모발·손톱·탈모의 보조치료용이라 모든 탈모에 쓰는 게 아니에요. 또 설폰아미드 제제와 함께 복용할 때는 의사 또는 약사와 상의하세요.\n\n복용 기간도 정해진 선이 있어요. 3~4개월 동안 복용해도 증상 개선이 없으면 복용을 즉각 중지하고 의사 또는 약사와 상의하세요. 보관은 25 ℃ 이하, 어린이 손이 닿지 않는 곳이 원칙이에요. 정해진 용법과 용량을 지키는 게 안전한 복용의 출발점이에요."
