        "data": "[{\"period\":\"첫 1~2주\",\"label\":\"표시 거의 없음\",\"desc\":\"연령 몫을 채워도 모발 성장 주기상 눈에 띄는 변화는 이른 시기예요. 여기서 끊으면 판단이 일러요(식약처 허가사항).\",\"color\":\"gray\"},{\"period\":\"평균 3~6개월\",\"label\":\"효과 판단 시험대\",\"desc\":\"허가사항이 적은 평균 치료기간. 나이에 맞는 하루 용량으로 이 구간을 통과한 뒤 개선이 없으면 중단하고 상담해요.\",\"color\":\"orange\"},{\"period\":\"이상 신호\",\"label\":\"두부 이외 발모 시 중단\",\"desc\":\"머리가 아닌 부위에 털이 자라면 효과와 무관하게 복용을 멈추고 의사·약사와 상의해요.\",\"color\":\"red\"}]"
