        "content": "이상반응을 결이 다른 갈래로 갈라 두면 대응이 쉬워져요. 식약처 허가사항이 적어둔 차례를 보면 위통·구토 같은 위장관 불쾌감이 가장 앞자리예요. 입으로 삼키는 1캡슐인 만큼 위장 쪽 자극이 먼저 와닿는 셈이죠. 두 번째 갈래는 몸 전체로 번지는 반응이에요. 발한, 빈맥, 홍조가 여기 묶여요. 땀·맥박·혈관 쪽으로 느껴지는 증상이죠. 세 번째 갈래는 가려움과 두드러기로 대표되는 과민·알레르기 신호고요. 두통과 어지럼처럼 머리 쪽으로 오는 증상도 함께 올라 있어요. 끝으로 따로 적힌 게 두부 이외 부위의 발모예요. 식약처 e약은요(품목번호 201506398)는 반응별 발생 빈도 수치까지는 내놓지 않아요. 숫자보다 '어느 계열인지'를 갈라 두는 편이 실전에 맞죠. 여기서 복용 타이밍이 들어와요. 위장 계열은 식후로 시점을 맞추면 덜 거슬리는 쪽이에요. 전신·과민 계열은 타이밍과 무관해요. 또렷하면 바로 멈추는 쪽이죠. 위장이 예민하거나 끼니가 들쭉날쭉한 분일수록 첫 갈래가 도드라질 수 있어요. 그 경우 성인 1일 3회를 식후 시점부터 단단히 잡아두면 돼요.",
        "sectionType": "comparison",
        "data": "[{\"label\":\"위장 계열\",\"value\":\"위통·구토 등 위장관 불쾌감\",\"note\":\"식후로 시점을 맞추면 자극이 줄어요. 빈속 복용 때 가장 거슬리는 갈래예요.\"},{\"label\":\"전신·순환기 계열\",\"value\":\"발한·빈맥·홍조\",\"note\":\"땀·맥박·혈관 쪽 반응. 타이밍과 무관하게 또렷하면 즉시 중단 후 상담이에요.\"},{\"label\":\"과민·신경계 계열\",\"value\":\"가려움·두드러기·두통·어지럼\",\"note\":\"알레르기 신호나 머리 쪽 증상. 과민증 이력이 있으면 특히 조심해요.\"},{\"label\":\"그 외 명시 신호\",\"value\":\"두부 이외 부위 발모\",\"note\":\"머리가 아닌 곳에 털이 나는 현상. 식약처가 별도로 적은 즉시 중단 신호죠.\"}]"
