        "content": "복용 금기 대상을 식약처 허가사항(품목번호 201506398)이 또박또박 나열해 뒀어요. 우선 이 약에 과민증이 있는 사람은 빼야 해요. 나이로는 12세 미만 소아가 제외고요. 탈모 유형으로 가면 흉터 탈모, 안드로젠 유전성 탈모증, 남성형 대머리가 금기 줄에 들어가요. 이유는 단순해요. 호르몬이나 흉터에서 비롯한 탈모를 노린 약이 아니라, 손상모·손톱 발육 부진·탈모 보조치료라는 좁은 적응증 안에서 쓰는 캡슐이라서예요. 임신했거나 임신 가능성이 있는 분, 수유 중인 분은 복용 전 의사·약사 상담이 먼저고요. 약끼리 부딪히는 경우도 챙겨야죠. 설폰아미드 제제와 같이 쓸 땐 상의하라고 허가사항에 분명히 적혀 있어요. 타이밍 관점도 있어요. 끼니에 맞춰 먹는 다른 약이 있으면 식후 복용끼리 겹치니 순서를 약사와 미리 정리해 둬요. 보관은 25℃ 이하, 습기와 빛을 피해 어린이 손이 안 닿는 자리에 둬요. 결국 내 나이와 탈모 유형이 적응증에 맞물리는지부터 가려 보고, 애매하면 약사에게 맡기는 게 순서랍니다."
